package com.yuegang.zhihui.ai.infrastructure;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.HttpServer;import com.yuegang.zhihui.ai.application.*;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.search.api.SearchHit;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.*;
class AiGatewaysTest{HttpServer server;String base;java.util.concurrent.atomic.AtomicReference<String> modelRequest=new java.util.concurrent.atomic.AtomicReference<>();@BeforeEach void start()throws Exception{server=HttpServer.create(new InetSocketAddress(0),0);base="http://localhost:"+server.getAddress().getPort();server.createContext("/api/v3/responses",x->{String request=new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);modelRequest.set(request);if(request.contains("\"model\":\"missing\"")){reply(x,404,"{\"error\":{\"code\":\"ModelNotFound\",\"message\":\"model is not active\"}}");return;}if(request.contains("\"model\":\"closed\"")){reply(x,404,"{\"error\":{\"code\":\"ModelNotOpen\",\"message\":\"Your account 9876543210 has not activated the model. Request id: req-secret-123\"}}");return;}reply(x,200,"{\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"model answer\"}]}]}");});server.createContext("/internal/v1/search/hybrid",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":[{\"documentId\":\"1\",\"chunkId\":\"2\",\"title\":\"t\",\"excerpt\":\"e\",\"lexicalScore\":1,\"vectorScore\":2,\"finalScore\":3}],\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.createContext("/api/v1/products/",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":{\"name\":\"snack\"},\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.createContext("/internal/v1/inventory/",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":{\"availableQuantity\":18},\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.createContext("/api/v1/orders/",x->reply(x,"{\"code\":\"SUCCESS\",\"message\":\"success\",\"data\":{\"status\":\"PAID\"},\"traceId\":\"t\",\"timestamp\":\"2026-01-01T00:00:00Z\"}"));server.start();}@AfterEach void stop(){server.stop(0);}static void reply(com.sun.net.httpserver.HttpExchange x,String s)throws java.io.IOException{reply(x,200,s);}static void reply(com.sun.net.httpserver.HttpExchange x,int status,String s)throws java.io.IOException{byte[]b=s.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().add("Content-Type","application/json");x.sendResponseHeaders(status,b.length);x.getResponseBody().write(b);x.close();}
@Test void modelRetrievalCommerceAndMetrics(){String arkBase=base+"/api/v3";assertThatThrownBy(()->new DoubaoModelGateway(arkBase,"","m")).isInstanceOf(IllegalStateException.class);ModelGateway model=new DoubaoModelGateway(arkBase,"key","m");assertThat(model.answer("s","u")).isEqualTo("model answer");assertThat(modelRequest.get()).contains("\"model\":\"m\"","\"instructions\":\"s\"","\"input\":\"u\"");ModelGateway webModel=new DoubaoModelGateway(arkBase,"key","m",true);assertThat(webModel.answerWithSources("s","u").text()).isEqualTo("model answer");assertThat(modelRequest.get()).contains("\"tools\":[{\"type\":\"web_search\"}]");assertThat(webModel.supportsWebSearch()).isTrue();assertThatThrownBy(()->new DoubaoModelGateway(arkBase,"key","missing").answer("s","u")).isInstanceOf(ModelProviderException.class).satisfies(error->{var provider=(ModelProviderException)error;assertThat(provider.httpStatus()).isEqualTo(404);assertThat(provider.providerCode()).isEqualTo("ModelNotFound");assertThat(provider.userMessage()).contains("已开通的模型 ID");});assertThatThrownBy(()->new DoubaoModelGateway(arkBase,"key","closed").answer("s","u")).isInstanceOf(ModelProviderException.class).satisfies(error->{var provider=(ModelProviderException)error;assertThat(provider.userMessage()).contains("模型尚未开通","Endpoint ID");assertThat(provider.providerMessage()).doesNotContain("9876543210","req-secret-123").contains("[REDACTED]");});byte[]secret="01234567890123456789012345678901".getBytes();var retrieval=new HttpRetrievalGateway(base,secret);assertThat(retrieval.search("q",null,5)).singleElement().extracting(SearchHit::finalScore).isEqualTo(3d);var tools=new CommerceToolGateway(base,base,secret,new ObjectMapper());assertThat(tools.product("3").digest()).hasSize(64);assertThat(tools.ownOrder(7,"8").name()).isEqualTo("OWN_ORDER_LOOKUP");var registry=new SimpleMeterRegistry();var measuredModel=new MeasuredModelGateway(model,registry);assertThat(measuredModel.answer("s","u")).isEqualTo("model answer");var measuredRetrieval=new MeasuredRetrievalGateway(retrieval,registry);assertThat(measuredRetrieval.search("q",null,2)).hasSize(1);var governance=mock(AiGovernanceService.class);when(governance.activeSystemPrompt()).thenReturn("governed");assertThat(new GovernedModelGateway((s,u)->s+u,governance).answer("x","u")).isEqualTo("governed\n\nxu");}
}
